<span class="font-code-metadata text-code-metadata text-text-subtle uppercase">Tujuan Penggunaan Terdaftar</span>
<p class="font-body-compact text-body-compact text-text-muted italic" id="m-purpose">
            Misi Pengintaian Celah Lembah Kelabu
          </p>
</div>
<div class="flex items-center gap-2 text-helper-text font-helper-text text-text-subtle pt-2">
<span class="material-symbols-outlined text-[16px] text-primary-container">shield</span>
<span>Segel Digital Dragonkeep #DRK-4091-VERIFIED • Arsip tidak dapat diubah secara sepihak</span>
</div>
</div>
<!-- Modal Footer -->
<div class="px-space-lg py-space-sm bg-surface-muted border-t border-border flex items-center justify-between">
<button class="flex items-center gap-1.5 px-3 py-1.5 rounded bg-surface border border-border text-text-muted hover:text-text-primary font-label-regular text-label-regular transition-colors" onclick="window.print()">
<span class="material-symbols-outlined text-[16px]">print</span>
<span>Cetak Surat Bukti</span>
</button>
<button class="px-4 py-2 rounded bg-primary-container text-gold-ink font-semibold font-label-regular text-label-regular hover:bg-gold-hover transition-colors" onclick="closeModal()">
          Tutup Rincian
        </button>
</div>
</div>
</div>
<!-- Inline Script for Client-Side Interactivity -->
<script>
    // Highlight Active Top Navigation Link for "Riwayat"
    (function highlightNav() {
      const links = document.querySelectorAll('header nav a');
      links.forEach(link => {
        if (link.getAttribute('data-path') === 'riwayat-rental') {
          link.classList.remove('text-text-muted', 'border-transparent');
          link.classList.add('text-primary-container', 'border-b-2', 'border-primary-container', 'font-semibold');
        } else {
          link.classList.remove('text-primary-container', 'border-primary-container', 'font-semibold');
          link.classList.add('text-text-muted', 'border-transparent');
        }
      });
    })();

    // Filtering & Search
    const searchInput = document.getElementById('ledger-search');
    const filterButtons = document.querySelectorAll('#filter-tabs .filter-btn');
    const rows = document.querySelectorAll('.ledger-row');
    const emptyState = document.getElementById('ledger-empty');
    const visibleCount = document.getElementById('visible-count');
    let currentStatus = 'all';

    function applyFilters() {
      const query = searchInput.value.toLowerCase().trim();
      let visible = 0;

      rows.forEach(row => {
        const rowStatus = row.getAttribute('data-status');
        const rowId = (row.getAttribute('data-id') || '').toLowerCase();
        const rowDragon = (row.getAttribute('data-dragon') || '').toLowerCase();
        const rowCode = (row.getAttribute('data-code') || '').toLowerCase();

        const matchesStatus = (currentStatus === 'all') || (rowStatus === currentStatus);
        const matchesQuery = !query || rowId.includes(query) || rowDragon.includes(query) || rowCode.includes(query);

        if (matchesStatus && matchesQuery) {
          row.style.display = '';
          visible++;
        } else {
          row.style.display = 'none';
        }
      });

      visibleCount.textContent = visible;
      if (visible === 0) {
        emptyState.classList.remove('hidden');
        emptyState.classList.add('flex');
      } else {
        emptyState.classList.add('hidden');
        emptyState.classList.remove('flex');
      }
    }

    filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        filterButtons.forEach(b => {
          b.classList.remove('bg-primary-container', 'text-gold-ink', 'font-semibold');
          b.classList.add('text-text-muted');
        });
        btn.classList.add('bg-primary-container', 'text-gold-ink', 'font-semibold');
        btn.classList.remove('text-text-muted');
        currentStatus = btn.getAttribute('data-status');
        applyFilters();
      });
    });

    searchInput.addEventListener('input', applyFilters);

    function resetFilters() {
      searchInput.value = '';
      currentStatus = 'all';
      filterButtons.forEach((b, idx) => {
        if (idx === 0) {
          b.classList.add('bg-primary-container', 'text-gold-ink', 'font-semibold');
          b.classList.remove('text-text-muted');
        } else {
          b.classList.remove('bg-primary-container', 'text-gold-ink', 'font-semibold');
          b.classList.add('text-text-muted');
        }
      });
      applyFilters();
    }

    // Modal Details Logic
    const modal = document.getElementById('modal-backdrop');
    function openModal(trxId, dragonName, dragonCode, dragonClass, loanDate, dueDate, returnDate, status, fine, rate, purpose) {
      document.getElementById('m-trx-id').textContent = trxId;
      document.getElementById('m-dragon-name').textContent = dragonName;
      document.getElementById('m-dragon-code').textContent = dragonCode;
      document.getElementById('m-dragon-class').textContent = dragonClass;
      document.getElementById('m-loan-date').textContent = loanDate;
      document.getElementById('m-due-date').textContent = dueDate;
      document.getElementById('m-return-date').textContent = returnDate;
      document.getElementById('m-fine').textContent = fine + ' Denda';
      document.getElementById('m-rate').textContent = rate;
      document.getElementById('m-purpose').textContent = purpose;

      const badge = document.getElementById('m-status-badge');
      if (status === 'Dikembalikan') {
        badge.className = 'px-2.5 py-1 rounded font-label-regular text-label-regular bg-status-available-bg text-status-available border border-[#2E5244] font-medium';
        badge.textContent = 'Selesai Dikembalikan';
      } else {
        badge.className = 'px-2.5 py-1 rounded font-label-regular text-label-regular bg-status-borrowed-bg text-status-borrowed border border-[#57442B] font-medium';
        badge.textContent = 'Sedang Berjalan (Dipinjam)';
      }

      modal.classList.remove('hidden');
      modal.classList.add('flex');
    }

    function closeModal() {
      modal.classList.add('hidden');
      modal.classList.remove('flex');
    }

    modal.addEventListener('click', (e) => {
      if (e.target === modal) {
        closeModal();
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && !modal.classList.contains('hidden')) {
        closeModal();
      }
    });

    // Simple toast indicator for export
    document.getElementById('btn-export-ledger').addEventListener('click', () => {
      const origText = document.getElementById('btn-export-ledger').innerHTML;
      document.getElementById('btn-export-ledger').innerHTML = '<span class="material-symbols-outlined text-[18px] text-status-available animate-spin">refresh</span><span>Mengunduh Dokumen...</span>';
      setTimeout(() => {
        document.getElementById('btn-export-ledger').innerHTML = '<span class="material-symbols-outlined text-[18px] text-status-available">check_circle</span><span>Tersimpan (PDF)</span>';
        setTimeout(() => {
          document.getElementById('btn-export-ledger').innerHTML = origText;
        }, 2000);
      }, 1000);
    });
  </script>
</div></main><footer class="w-full bg-surface-muted border-t border-border mt-auto"><div class="max-w-7xl mx-auto px-margin md:px-margin-tablet lg:px-margin-desktop py-space-lg flex flex-col sm:flex-row items-center justify-between gap-space-md font-helper-text text-helper-text text-text-subtle"><div class="flex items-center gap-space-sm"><span class="font-section-title text-card-title text-primary leading-none">᚛ᚇ᚜</span><span>DracoRent Guild Ledger — Registri Resmi Serikat Penjaga Naga</span></div><div class="flex items-center gap-space-lg"><span class="font-code-metadata text-code-metadata text-text-subtle">ARSIP RESMI SERIKAT • ERA KEEMASAN KE-IV</span></div></div></footer><script>
(function() {
  const pathMap = {
    'masuk': 'masuk.html',
    'masuk-kurator': 'masuk.html',
    'keluar': 'masuk.html',
    'ringkasan': 'ringkasan.html',
    'unit-naga': 'unit-naga.html',
    'tambah-unit-modal': 'tambah-unit-modal.html',
    'kategori': 'kategori.html',
    'anggota': 'anggota.html',
    'pinjaman-aktif': 'pinjaman-aktif.html',
    'riwayat-dan-laporan': 'riwayat-dan-laporan.html',
    'katalog-naga': 'katalog-naga.html',
    'katalog-publik': 'katalog-naga.html',
    'detail-naga': 'detail-naga.html',
    'pinjaman-saya': 'pinjaman-saya.html',
    'riwayat-rental': 'riwayat-rental.html',
    'profil-saya': 'profil-saya.html'
  };

  function navigateTo(slug) {
    const target = pathMap[slug] || (slug + '.html');
    if (window.parent && window.parent !== window && window.parent.switchDracoScreen) {
      window.parent.switchDracoScreen(slug);
      return;
    }
    const inScreensDir = window.location.pathname.replace(/\\/g, '/').includes('/screens/');
    window.location.href = inScreensDir ? target : ('screens/' + target);
  }

  document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('[data-path]').forEach(function(el) {
      el.addEventListener('click', function(e) {
        const p = el.getAttribute('data-path');
        if (p && pathMap[p]) {
          e.preventDefault();
          navigateTo(p);
        }
      });
    });

    // Wire catalog detail & rent buttons to detail-naga screen
    document.querySelectorAll('.view-detail-btn, .rent-action-btn').forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        navigateTo('detail-naga');
      });
    });

    // Wire breadcrumb back to catalog
    document.querySelectorAll('a').forEach(function(a) {
      const txt = (a.textContent || '').trim();
      if (txt.includes('Kembali ke Katalog')) {
        a.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('katalog-naga');
        });
      }
      if (txt.includes('Lihat Semua Kontrak')) {
        a.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
    });

    // Wire Proses Pengembalian buttons on dashboard
    document.querySelectorAll('button').forEach(function(btn) {
      const txt = (btn.textContent || '').trim();
      if (txt.includes('Proses Pengembalian')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
      if (txt.includes('+ Tambah Unit Baru') || txt.includes('Tambah Unit Naga')) {
        btn.addEventListener('click', function(e) {
          if (!document.getElementById('modal-backdrop') && !window.location.pathname.includes('tambah-unit-modal')) {
            e.preventDefault();
            navigateTo('tambah-unit-modal');
          }
        });
      }
      if (txt.includes('Kelola Kategori')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('kategori');
        });
      }
      if (txt.includes('+ Tambah Anggota Serikat') && !document.getElementById('panel-tambah-anggota')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('anggota');
        });
      }
      if (txt.includes('Semua Pinjaman Aktif')) {
        btn.addEventListener('click', function(e) {
          e.preventDefault();
          navigateTo('pinjaman-aktif');
        });
      }
    });

    // Wire login form submit
    const loginForm = document.getElementById('loginForm');
    if (loginForm) {
      loginForm.addEventListener('submit', function(e) {
        e.preventDefault();
        const emailVal = (document.getElementById('email')?.value || '').toLowerCase();
        if (emailVal.includes('admin') || emailVal.includes('kaelen') || emailVal.includes('kurator')) {
          navigateTo('ringkasan');
        } else {
          navigateTo('katalog-naga');
        }
      });
    }
  });
})();
</script>
<script src="/js/dracorent-app.js"></script></body></html>


